window.MATH_CURRICULUM = [{"id":"g1-01","grade":1,"name":"正の数・負の数","topics":["正と負","数直線","絶対値","加減乗除","累乗・四則の混合"],"rules":["0より大きい数は正、0より小さい数は負。0はどちらでもない。","加法は絶対値と符号に注目。減法は「反対の数を足す」。","乗除は同符号で正、異符号で負。かっこ→累乗→乗除→加減の順。"],"example":"−3＋5＝2、−3×(−4)＝12","order":0},{"id":"g1-02","grade":1,"name":"文字の式","topics":["文字式の表し方","代入","一次式の計算","数量の関係"],"rules":["文字式では × を省略し、数字を文字の前に書く（3×a＝3a）。","同じ文字の項（同類項）は係数を足し引きできる。","代入は文字を数に置き換える。負の数を代入するときはかっこを使う。"],"example":"2a＋3a＝5a、a＝−2 のとき 3a＝−6","order":1},{"id":"g1-03","grade":1,"name":"一次方程式","topics":["等式の性質","移項","かっこ・分数","文章題"],"rules":["等式の両辺に同じ数を足し引きしても等式は成り立つ。","移項すると項の符号が変わる。","文章題は「何をxとするか」を決めて式にする。"],"example":"3x＋2＝11 → 3x＝9 → x＝3","order":2},{"id":"g1-04","grade":1,"name":"比例と反比例","topics":["座標","比例 y=ax","反比例 y=a/x","グラフ"],"rules":["比例は y＝ax。xが2倍ならyも2倍。","反比例は y＝a/x。xとyの積が一定。","比例のグラフは原点を通る直線、反比例は曲線。"],"example":"y＝3x で x＝4なら y＝12","order":3},{"id":"g1-05","grade":1,"name":"平面図形","topics":["図形の移動","基本の作図","円・おうぎ形"],"rules":["対頂角は等しく、一直線上の角の和は180°。","垂直二等分線上の点は線分の両端から等距離。","おうぎ形の面積は πr²×中心角/360°。"],"example":"半径6cm・中心角60°のおうぎ形の面積は6πcm²","order":4},{"id":"g1-06","grade":1,"name":"空間図形","topics":["立体の種類","見取図","展開図","表面積・体積"],"rules":["直方体の体積は 縦×横×高さ。","柱体の体積は 底面積×高さ、錐体はその1/3。","円柱の表面積は 2πr²＋2πrh。"],"example":"3×4×5 の直方体の体積は60cm³","order":5},{"id":"g1-07","grade":1,"name":"データの活用","topics":["度数分布","代表値","ヒストグラム","相対度数"],"rules":["平均値は合計÷個数。中央値は順序の中央にある値。","範囲は最大値−最小値。","相対度数はその階級の度数÷全体の度数。"],"example":"3,4,5,10 の平均は5.5","order":6},{"id":"g2-01","grade":2,"name":"式の計算","topics":["多項式","単項式","式の四則計算","文字式による説明"],"rules":["同類項だけをまとめる。","かっこの前が − なら中の符号を変える。","文字式を使うと整数の性質を一般的に説明できる。"],"example":"2(3a−b)＝6a−2b","order":7},{"id":"g2-02","grade":2,"name":"連立方程式","topics":["加減法","代入法","文章題"],"rules":["2つの式を同時に成り立たせるxとyを探す。","加減法では係数をそろえて文字を1つ消す。","求めた解は両方の式に代入して確かめる。"],"example":"x＋y＝7、x−y＝1 → x＝4、y＝3","order":8},{"id":"g2-03","grade":2,"name":"一次関数","topics":["y=ax+b","傾き・切片","変域","交点・文章題"],"rules":["一次関数は y＝ax＋b。aは傾き、bは切片。","傾き＝yの増加量÷xの増加量。","2直線の交点は連立方程式で求められる。"],"example":"y＝2x＋3 なら傾き2、切片3","order":9},{"id":"g2-04","grade":2,"name":"平行と合同","topics":["平行線と角","多角形","合同条件","証明の基礎"],"rules":["三角形の内角の和は180°。n角形の内角の和は(n−2)×180°。","平行線の同位角・錯角は等しい。","合同条件は3辺、2辺とその間の角、1辺とその両端の角。"],"example":"五角形の内角の和は540°","order":10},{"id":"g2-05","grade":2,"name":"三角形と四角形","topics":["二等辺三角形","直角三角形","平行四辺形","証明"],"rules":["二等辺三角形の底角は等しい。","平行四辺形は向かい合う辺・角が等しく、対角線が互いの中点で交わる。","証明は仮定→根拠→結論の順に書く。"],"example":"頂角40°の二等辺三角形の底角は70°","order":11},{"id":"g2-06","grade":2,"name":"確率","topics":["場合の数","樹形図","確率","反復試行"],"rules":["起こりうるすべての場合をもれなく、重複なく数える。","確率＝条件に合う場合の数÷すべての場合の数。","確率は0以上1以下。"],"example":"公平なサイコロで偶数が出る確率は1/2","order":12},{"id":"g2-07","grade":2,"name":"データの比較","topics":["四分位数","箱ひげ図","四分位範囲","データ比較"],"rules":["中央値でデータを上下に分け、それぞれの中央値が第1・第3四分位数。","四分位範囲＝第3四分位数−第1四分位数。","箱ひげ図では中央値や散らばりを比較する。"],"example":"第1四分位数3、第3四分位数9なら四分位範囲6","order":13},{"id":"g3-01","grade":3,"name":"式の展開と因数分解","topics":["乗法公式","式の展開","共通因数","因数分解"],"rules":["(a＋b)²＝a²＋2ab＋b²。","(a＋b)(a−b)＝a²−b²。","因数分解は展開の逆。共通因数をまず探す。"],"example":"x²−9＝(x＋3)(x−3)","order":14},{"id":"g3-02","grade":3,"name":"平方根","topics":["無理数","平方根","根号の計算","分母の有理化"],"rules":["a＞0の平方根は±√a。記号√aは正の平方根を表す。","√a×√b＝√(ab)（a,b≥0）。","√8＝2√2のように根号内の平方数を外に出せる。"],"example":"√49＝7、49の平方根は±7","order":15},{"id":"g3-03","grade":3,"name":"二次方程式","topics":["平方根による解法","因数分解","解の公式","文章題"],"rules":["x²＝a（a＞0）なら x＝±√a。","積が0なら、少なくとも一方が0。","ax²＋bx＋c＝0の解の公式で求められる。"],"example":"(x−2)(x＋3)＝0 → x＝2,−3","order":16},{"id":"g3-04","grade":3,"name":"関数 y=ax²","topics":["二次関数の表とグラフ","変域","変化の割合","利用"],"rules":["y＝ax²のグラフは原点を頂点とする放物線。","xを2倍にするとyは4倍になる。","区間の変化の割合は（yの増加量）÷（xの増加量）。"],"example":"y＝2x²でx＝−3ならy＝18","order":17},{"id":"g3-05","grade":3,"name":"相似な図形","topics":["相似条件","線分比","面積比","体積比","相似の証明"],"rules":["相似な図形の対応する角は等しく、辺の比は一定。","相似比が1:kなら面積比1:k²、体積比1:k³。","三角形の相似条件は3辺の比・2辺の比とその間の角・2角。"],"example":"相似比2:3なら面積比4:9","order":18},{"id":"g3-06","grade":3,"name":"円の性質","topics":["円周角","中心角","円周角の定理","図形問題"],"rules":["同じ弧に対する円周角は中心角の半分。","同じ弧に対する円周角は等しい。","半円に対する円周角は90°。"],"example":"中心角100°に対する円周角は50°","order":19},{"id":"g3-07","grade":3,"name":"三平方の定理","topics":["定理と逆","直角三角形","平面・空間への応用"],"rules":["直角三角形の2辺a,bと斜辺cには a²＋b²＝c²。","最長の辺の2乗が他の2辺の2乗の和なら直角三角形。","図形内の直角三角形を見つけることが応用の鍵。"],"example":"直角をはさむ辺が3,4なら斜辺は5","order":20},{"id":"g3-08","grade":3,"name":"標本調査","topics":["全数調査","標本調査","無作為抽出","推定"],"rules":["全数調査は全員・全件、標本調査は一部を調べる。","偏りを減らすには無作為抽出が重要。","標本の割合を使って母集団の規模を推定できる。"],"example":"200人中60人が賛成なら賛成率は30%","order":21}];
